    {
      "id": "extractContractFields",
      "type": "uipath.ixp.employment-agreements-d4ee40a0-ixp.97f6f1c4-2b0d-8044-8892-c8809e742924-c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
      "typeVersion": "1.0.0",
      "display": {
        "label": "Extract Contract Fields"
      },
      "inputs": {
        "model": {
          "id": "97f6f1c4-2b0d-8044-8892-c8809e742924",
          "modelName": "employment-agreements-d4ee40a0-ixp",
          "modelDisplayName": "employment-agreements-d4ee40a0-ixp",
          "folderKey": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
          "folderName": "Shared",
          "folderPath": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
          "description": ""
        },
        "modelName": "employment-agreements-d4ee40a0-ixp",
        "projectName": "employment-agreements-d4ee40a0-ixp",
        "folderKey": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
        "folderName": "Shared",
        "versionTag": "",
        "pageRange": "",
        "fileRef": "=js:$vars.start.output.contractFile"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Extraction result from the IxP model",
          "source": "=this.result",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "parseContractData",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Parse Contract Data"
      },
      "inputs": {
        "script": "const fields = ($vars.extractContractFields.output.ExtractionResult && $vars.extractContractFields.output.ExtractionResult.ResultsDocument && $vars.extractContractFields.output.ExtractionResult.ResultsDocument.Fields) ? $vars.extractContractFields.output.ExtractionResult.ResultsDocument.Fields : [];\nconst findField = (name) => { const f = fields.find(function(x){ return x.FieldName === name; }); return f && f.Values && f.Values.length > 0 ? f.Values[0] : null; };\nconst partyNames = [findField('party_name'), findField('employer_name'), findField('employee_name'), findField('Party Name'), findField('Employer Name'), findField('Employee Name')].filter(function(v){ return v !== null; });\nconst effectiveDate = findField('effective_date') || findField('Effective Date') || findField('start_date') || findField('Start Date') || null;\nconst terminationClause = findField('termination_clause') || findField('Termination Clause') || findField('termination') || findField('Termination') || null;\nreturn { partyNames: partyNames, effectiveDate: effectiveDate, terminationClause: terminationClause, rawFieldCount: fields.length };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Parsed contract fields: partyNames, effectiveDate, terminationClause",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=result.Error",
          "var": "error"
        }
      }
    },
    {
      "id": "approvalStep",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": {
        "label": "Contract Approval"
      },
      "inputs": {
        "title": "Contract Approval Required",
        "message": "=js:\"Please review the extracted contract data and approve or reject.\\n\\nParty Names: \" + ($vars.parseContractData.output.partyNames || []).join(\", \") + \"\\nEffective Date: \" + ($vars.parseContractData.output.effectiveDate || \"Not found\") + \"\\nTermination Clause: \" + ($vars.parseContractData.output.terminationClause || \"Not found\"),
        "fields": [
          {
            "id": "decision",
            "label": "Decision",
